/// Binary search over a sorted `&[(&str, T)]` table.
fn lookup<T: Copy>(table: &[(&str, T)], key: &str) -> Option<T> {
    table.binary_search_by(|(k, _)| (*k).cmp(key)).ok().map(|i| table[i].1)
}

/// Glyph name -> Unicode, for fonts with no usable `/ToUnicode` CMap.
pub fn glyph_to_unicode(name: &str) -> Option<char> {
    if let Some(c) = lookup(GLYPH_TO_UNICODE, name) {
        return Some(c);
    }
    // pdfminer's `name2unicode` also understands the algorithmic `uniXXXX` and
    // `uXXXX[XX]` forms, which no static table can enumerate.
    if let Some(hex) = name.strip_prefix("uni") {
        // `.len() >= 4` is a byte count; glyph names are ASCII by PDF spec convention, but
        // an out-of-spec name with a non-ASCII byte before the 4-byte mark would otherwise
        // make `&hex[..4]` panic on a non-char-boundary index (same class of bug as
        // layout.rs's is_heading_marker -- see CATCHUP_PLAN.md's 2026-08-22 entry).
        // `is_char_boundary` is the direct, zero-cost way to make this slice provably safe.
        if hex.len() >= 4 && hex.is_char_boundary(4) {
            if let Ok(cp) = u32::from_str_radix(&hex[..4], 16) {
                return char::from_u32(cp);
            }
        }
    }
    if let Some(hex) = name.strip_prefix('u') {
        if (4..=6).contains(&hex.len()) {
            if let Ok(cp) = u32::from_str_radix(hex, 16) {
                return char::from_u32(cp);
            }
        }
    }
    None
}

/// Standard-14 metrics for `name`, including the common aliases (Arial ->
/// Helvetica and so on) that pdfminer resolves through `FONT_METRICS`. A
/// subset-font prefix (`ABCDEF+Helvetica`) is stripped first.
pub fn standard_14(
    name: &str,
) -> Option<(&'static [(&'static str, i32)], f64, f64, (f64, f64, f64, f64))> {
    let base = name.rsplit('+').next().unwrap_or(name);
    let canonical = match base {
        "Arial" | "ArialMT" | "Arial,Regular" => "Helvetica",
        "Arial-Bold" | "Arial-BoldMT" | "Arial,Bold" => "Helvetica-Bold",
        "Arial-Italic" | "Arial-ItalicMT" | "Arial,Italic" => "Helvetica-Oblique",
        "Arial-BoldItalic" | "Arial-BoldItalicMT" | "Arial,BoldItalic" => "Helvetica-BoldOblique",
        "CourierNew" | "CourierNewPSMT" => "Courier",
        "CourierNew,Bold" | "CourierNewPS-BoldMT" => "Courier-Bold",
        "CourierNew,Italic" | "CourierNewPS-ItalicMT" => "Courier-Oblique",
        "CourierNew,BoldItalic" | "CourierNewPS-BoldItalicMT" => "Courier-BoldOblique",
        "TimesNewRoman" | "TimesNewRomanPSMT" | "Times" => "Times-Roman",
        "TimesNewRoman,Bold" | "TimesNewRomanPS-BoldMT" => "Times-Bold",
        "TimesNewRoman,Italic" | "TimesNewRomanPS-ItalicMT" => "Times-Italic",
        "TimesNewRoman,BoldItalic" | "TimesNewRomanPS-BoldItalicMT" => "Times-BoldItalic",
        other => other,
    };
    STANDARD_14
        .iter()
        .find(|(n, ..)| *n == canonical)
        .map(|(_, w, a, d, bb)| (*w, *a, *d, *bb))
}

/// Width lookup within one Standard-14 font's table.
///
/// The key is the Unicode *character* the code maps to (" ", "A"), NOT the
/// glyph name ("space", "A") -- pdfminer's `FONT_METRICS` tables are keyed that
/// way, which is why `char_width`'s `widths[to_unichr(cid)]` attempt is the one
/// that succeeds for a base-14 font carrying no `/Widths` array.
pub fn standard_width(widths: &[(&str, i32)], unicode_text: &str) -> Option<i32> {
    lookup(widths, unicode_text)
}

